xpath.script:
// 
    function setDocType(type) {
        var cardB = document.getElementById('card_doc_boleta');
        var cardF = document.getElementById('card_doc_factura');
        var radioB = document.getElementById('radio_boleta');
        var radioF = document.getElementById('radio_factura');

        var compNameDiv = document.querySelector('div[id*="company_name"]') || document.querySelector('input[name="company_name"]')?.closest('.form-group') || document.querySelector('input[name="company_name"]')?.closest('div');
        var vatInput = document.querySelector('input[name="vat"]');
        var vatLabel = vatInput ? vatInput.closest('.form-group')?.querySelector('label') : null;
        var nameLabel = document.querySelector('input[name="name"]')?.closest('.form-group')?.querySelector('label');
        var nameInput = document.querySelector('input[name="name"]');

        if (type === 'factura') {
            if (cardF) cardF.classList.add('active');
            if (cardB) cardB.classList.remove('active');
            if (radioF) radioF.checked = true;
            if (compNameDiv) {
                compNameDiv.style.display = 'block';
                var compLabel = compNameDiv.querySelector('label');
                if (compLabel) compLabel.innerHTML = 'Razón Social <span class="text-danger">*</span>';
                var compInput = compNameDiv.querySelector('input');
                if (compInput) compInput.placeholder = 'Ej: Inversiones Wanka S.A.C.';
            }
            if (vatLabel) vatLabel.innerHTML = 'RUC <span class="text-danger">*</span>';
            if (vatInput) {
                vatInput.placeholder = 'Ej: 20506146039 (11 dígitos)';
                vatInput.required = true;
                vatInput.maxLength = 11;
            }
            if (nameLabel) nameLabel.innerHTML = 'Nombre de Contacto / Representante <span class="text-danger">*</span>';
            if (nameInput) nameInput.placeholder = 'Ej: Carlos Mendoza';
        } else {
            if (cardB) cardB.classList.add('active');
            if (cardF) cardF.classList.remove('active');
            if (radioB) radioB.checked = true;
            if (compNameDiv) compNameDiv.style.display = 'none';
            if (vatLabel) vatLabel.innerHTML = 'DNI (Documento de Identidad) <span class="text-danger">*</span>';
            if (vatInput) {
                vatInput.placeholder = 'Ej: 72345678 (8 dígitos)';
                vatInput.required = false;
                vatInput.maxLength = 8;
            }
            if (nameLabel) nameLabel.innerHTML = 'Nombre Completo <span class="text-danger">*</span>';
            if (nameInput) nameInput.placeholder = 'Ej: Juan Carlos Pérez Gómez';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        // Inicializar en Boleta (persona natural por defecto)
        setDocType('boleta');

        // Ocultar campo de Código Postal innecesario en Perú y dar valor default
        var zipInput = document.querySelector('input[name="zip"]');
        if (zipInput) {
            var zipContainer = zipInput.closest('.form-group') || zipInput.closest('div[class*="col-"]');
            if (zipContainer) zipContainer.style.display = 'none';
            if (!zipInput.value) zipInput.value = '15001';
        }

        // Transformar Calle 2 en Referencia de Entrega (Vital en Perú)
        var street2Input = document.querySelector('input[name="street2"]');
        if (street2Input) {
            var street2Container = street2Input.closest('.form-group') || street2Input.closest('div[class*="col-"]');
            if (street2Container) {
                street2Container.style.display = 'block';
                street2Container.style.order = '10';
                street2Container.style.width = '100%';
                var street2Label = street2Container.querySelector('label');
                if (street2Label) street2Label.textContent = 'Referencia de Entrega (Opcional)';
                street2Input.placeholder = 'Ej: Dpto 302, frente al parque o portón blanco';
            }
        }

        // Auto-seleccionar Perú si está vacío para desplegar Departamento de inmediato
        var countrySelect = document.querySelector('select[name="country_id"]');
        if (countrySelect && (!countrySelect.value || countrySelect.value === '')) {
            for (var i = 0; i < countrySelect.options.length; i++) {
                var optTxt = countrySelect.options[i].text.toLowerCase();
                if (optTxt.includes('peru') || optTxt.includes('perú')) {
                    countrySelect.selectedIndex = i;
                    if (window.$) {
                        $(countrySelect).trigger('change');
                    } else {
                        countrySelect.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                    break;
                }
            }
        }

        // Formatear cantidades en el Resumen (quitar el decimal 3.0)
        var qtyCells = document.querySelectorAll('.td-qty div, td.td-qty');
        qtyCells.forEach(function(c) {
            var txt = c.textContent.trim();
            if (txt.endsWith('.0')) {
                c.textContent = parseInt(txt, 10);
            }
        });

        // ══════════════════════════════════════════════════════════
        // CASCADA DINÁMICA: DEPARTAMENTO -> PROVINCIA -> DISTRITO
        // ══════════════════════════════════════════════════════════
        var stateSelect = document.querySelector('select[name="state_id"]');
        var cityContainer = document.querySelector('div[id*="div_city"]') || document.querySelector('.div_city');
        var cityInput = document.querySelector('input[name="city"]');

        if (stateSelect && cityContainer && cityInput) {
            var stateLabel = stateSelect.closest('.form-group')?.querySelector('label');
            if (stateLabel) stateLabel.innerHTML = 'Departamento <span class="text-danger">*</span>';

            var origCityLabel = cityContainer.querySelector('label');
            if (origCityLabel) origCityLabel.style.display = 'none';

            cityInput.type = 'hidden';

            var cascadeWrapper = document.getElementById('wango_cascade_geo_wrapper');
            if (!cascadeWrapper) {
                cascadeWrapper = document.createElement('div');
                cascadeWrapper.id = 'wango_cascade_geo_wrapper';
                cascadeWrapper.className = 'row w-100 m-0 p-0';
                cascadeWrapper.innerHTML = `
                    <div class="col-12 col-md-6 pl-0 pr-md-2 mb-3">
                        <label class="col-form-label font-weight-bold text-dark">Provincia <span class="text-danger">*</span></label>
                        <select id="wango_checkout_sel_prov" class="form-control" style="border-radius: 10px; height: 48px; border: 1.5px solid #e2e8f0;">
                            <option value="">-- Selecciona Provincia --</option>
                        </select>
                    </div>
                    <div class="col-12 col-md-6 pr-0 pl-md-2 mb-3">
                        <label class="col-form-label font-weight-bold text-dark">Distrito <span class="text-danger">*</span></label>
                        <select id="wango_checkout_sel_dist" class="form-control" style="border-radius: 10px; height: 48px; border: 1.5px solid #e2e8f0;">
                            <option value="">-- Selecciona Distrito --</option>
                        </select>
                    </div>
                `;
                cityContainer.appendChild(cascadeWrapper);
            }

            var selProv = document.getElementById('wango_checkout_sel_prov');
            var selDist = document.getElementById('wango_checkout_sel_dist');

            function updateBackendCity() {
                var pText = selProv.options[selProv.selectedIndex]?.text || '';
                var dText = selDist.options[selDist.selectedIndex]?.text || '';
                if (pText && dText && selProv.value && selDist.value) {
                    cityInput.value = dText + ', ' + pText;
                    localStorage.setItem('wango_del_prov_name', pText);
                    localStorage.setItem('wango_del_dist_name', dText);
                    localStorage.setItem('wango_del_dist_id', selDist.value);
                }
            }

            function loadProvinces(deptId, preselectedProvName) {
                selProv.innerHTML = '<option value="">Cargando provincias...</option>';
                selDist.innerHTML = '<option value="">-- Selecciona Distrito --</option>';
                if (!deptId) {
                    selProv.innerHTML = '<option value="">-- Selecciona Provincia --</option>';
                    return;
                }
                fetch('/shop/delivery/locations', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({params: {department_id: deptId}})
                })
                .then(function(r){ return r.json(); })
                .then(function(data){
                    var provs = data.result || [];
                    selProv.innerHTML = '<option value="">-- Selecciona Provincia --</option>';
                    provs.forEach(function(p){
                        var opt = document.createElement('option');
                        opt.value = p.id;
                        opt.textContent = p.name;
                        if (preselectedProvName && p.name.toLowerCase() === preselectedProvName.toLowerCase()) {
                            opt.selected = true;
                        }
                        selProv.appendChild(opt);
                    });
                    if (selProv.value) {
                        loadDistricts(selProv.value, localStorage.getItem('wango_del_dist_name'));
                    }
                })
                .catch(function(e){
                    console.error('Error cargando provincias:', e);
                    selProv.innerHTML = '<option value="">-- Error al cargar --</option>';
                });
            }

            function loadDistricts(provId, preselectedDistName) {
                selDist.innerHTML = '<option value="">Cargando distritos...</option>';
                if (!provId) {
                    selDist.innerHTML = '<option value="">-- Selecciona Distrito --</option>';
                    return;
                }
                fetch('/shop/delivery/locations', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({params: {province_id: provId}})
                })
                .then(function(r){ return r.json(); })
                .then(function(data){
                    var dists = data.result || [];
                    selDist.innerHTML = '<option value="">-- Selecciona Distrito --</option>';
                    dists.forEach(function(d){
                        var opt = document.createElement('option');
                        opt.value = d.id;
                        opt.textContent = d.name;
                        if (preselectedDistName && d.name.toLowerCase() === preselectedDistName.toLowerCase()) {
                            opt.selected = true;
                        }
                        selDist.appendChild(opt);
                    });
                    updateBackendCity();
                })
                .catch(function(e){
                    console.error('Error cargando distritos:', e);
                    selDist.innerHTML = '<option value="">-- Error al cargar --</option>';
                });
            }

            stateSelect.addEventListener('change', function(){
                loadProvinces(this.value);
            });
            if (window.$) {
                $(stateSelect).on('change', function(){
                    loadProvinces($(this).val());
                });
            }
            selProv.addEventListener('change', function(){
                loadDistricts(this.value);
            });
            selDist.addEventListener('change', function(){
                updateBackendCity();
            });

            function triggerInitialLoad() {
                var initialDept = stateSelect.value;
                var savedDeptId = localStorage.getItem('wango_del_dept_id');
                var savedDeptName = localStorage.getItem('wango_del_dept_name');
                var savedProv = localStorage.getItem('wango_del_prov_name');
                var savedStreet = localStorage.getItem('wango_del_exact_street');

                var streetInput = document.querySelector('input[name="street"]');
                if (streetInput && !streetInput.value && savedStreet) {
                    streetInput.value = savedStreet;
                }

                if (!initialDept && (savedDeptId || savedDeptName)) {
                    for (var i = 0; i < stateSelect.options.length; i++) {
                        var opt = stateSelect.options[i];
                        if (opt.value == savedDeptId || (savedDeptName && opt.text.toLowerCase().includes(savedDeptName.toLowerCase()))) {
                            stateSelect.selectedIndex = i;
                            initialDept = opt.value;
                            break;
                        }
                    }
                }
                if (initialDept) {
                    loadProvinces(initialDept, savedProv);
                }
            }
            setTimeout(triggerInitialLoad, 300);
            setTimeout(triggerInitialLoad, 1000);
        }
    });
//
